<script setup lang="ts">
import CycleSummary from './CycleSummary.vue'
import FormSection from './FormSection.vue'
import {dateText,label,type Row} from '../experiments/model'
import {stages} from '../measurements/model'
defineProps<{sample:Row}>()
const evidence:Record<string,string>={not_confirmed:'仅绑定，未确认处理',voided:'执行已作废，不计累计',recorded_time:'已记录装载与实际执行时间',recorded_loading:'已记录装载与取出'}
function node(e:Row|null){return e?`${e.step_index==null?'步骤未记录':`步骤 ${e.step_index}`} · ${e.event_at?dateText(e.event_at):'时间未记录'}`:'未确认'}
function source(sample:Row,id:number){return sample.research_review?.measurements?.find((m:Row)=>m.measurement_id===id)}
</script>
<template><FormSection title="实验科研履历" description="每次执行独立保留；已知时间按实际顺序，时间未知按执行记录顺序。绑定不等于实际处理。">
<CycleSummary :summary="sample.participation_summary"/>
<p v-if="!sample.experiments?.length" class="readonly-note">尚无关联实验，记录实际执行后会自动出现在这里。</p>
<el-timeline v-else class="sample-research-timeline" data-testid="sample-experiments">
<el-timeline-item v-for="row in sample.experiments" :key="row.process_id" :timestamp="row.started_at?dateText(row.started_at):'时间未知 · 按执行记录顺序'" placement="top" :type="row.cycles_confirmed?'primary':'info'" :hollow="!row.cycles_confirmed">
<article class="research-event"><header><div><router-link :to="{path:'/processes',query:{process_id:row.process_id}}" class="research-title">{{row.plan_title||'独立实验'}}</router-link><p>{{row.process_code}} · {{label(row.process_mode)}}</p></div><span class="research-status" :class="{'is-unconfirmed':!row.cycles_confirmed}">{{row.cycles_confirmed?`${row.full_ale_cycles} cycles · 已确认`:evidence[row.execution_evidence]||'参与依据未知'}}</span></header>
<p class="participation-nodes">装载：{{node(row.load_event)}}<br/>取出：{{node(row.unload_event)}}</p>
<div v-if="row.measurements?.length" class="history-measurements"><div v-for="m in row.measurements" :key="m.measurement_id" class="history-measurement"><div><router-link :to="{path:'/measurements',query:{id:m.measurement_id}}">{{stages[m.stage]||m.stage||'阶段未记录'}} · {{m.measurement_code}}</router-link><p>{{m.measured_at?dateText(m.measured_at):'测量时间未记录'}}<span v-if="source(sample,m.measurement_id)"> · {{source(sample,m.measurement_id).model_name||'模型未记录'}}</span></p></div><strong>{{m.thickness_mean_nm??'未记录'}} <small>nm</small></strong><router-link v-if="source(sample,m.measurement_id)?.source_file_id" :to="{path:'/source-files',query:{id:source(sample,m.measurement_id).source_file_id}}">原件</router-link></div></div><p v-else class="field-hint">本次尚无正式测量。</p>
<details><summary>实际处理条件与参数</summary><div class="history-condition-grid"><p>R1 {{row.r1_temp_c??'未记录'}} °C / R2 {{row.r2_temp_c??'未记录'}} °C</p><p>N₂ {{row.n2_flow_sccm??'未记录'}} sccm</p><p>O₃ 预处理 {{row.o3_pre_cycles??'未记录'}} · HF/TMA {{row.hf_tma_repeats??'未记录'}}</p><p>体系 {{row.chemistry_name||'未确认'}}</p></div><p>{{evidence[row.execution_evidence]}}<span v-if="row.ended_at"> · 结束 {{dateText(row.ended_at)}}</span></p><p v-if="!row.cycles_confirmed&&row.cycles_recorded">填写循环值 {{row.full_ale_cycles}}（缺少依据，不计累计）</p><p v-if="row.sample_role_note">{{row.sample_role_note}}</p><details v-if="row.steps?.length"><summary>实际步骤与参数（执行记录值）</summary><div v-for="s in row.steps" :key="s.step_id"><strong>{{s.step_index}} · {{s.step_name||label(s.step_kind)}}</strong><template v-if="s.parameter_snapshot"><div v-if="s.parameter_snapshot.temperature">温度 {{s.parameter_snapshot.temperature.value??'未记录'}} {{s.parameter_snapshot.temperature.unit}}</div><div v-for="g in s.parameter_snapshot.groups" :key="g.name">{{g.name}}：<span v-for="f in g.fields" :key="f.name">{{f.name}} {{f.value??'未记录'}} {{f.unit}}；</span></div></template><p v-else>旧版参数请打开实验查看，未自动换算。</p></div></details></details>
<router-link class="el-button is-link" :to="{path:'/processes',query:{process_id:row.process_id}}">打开实验</router-link></article>
</el-timeline-item></el-timeline></FormSection></template>
<style scoped>.sample-research-timeline{padding:14px 0 0 10px;margin:0}.research-event{padding:18px 20px;border:1px solid var(--line);border-radius:12px;background:#f8fafc;box-shadow:4px 4px 12px #c7d3dc35,-3px -3px 10px #fff}.research-event header{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.research-title{font-size:16px;font-weight:650;color:#086d79;line-height:1.7}.research-event p{font-size:12px;color:var(--muted);line-height:1.8;margin:5px 0}.research-status{padding:4px 8px;border:1px solid #99c9c4;background:#eef7f5;color:#1d6357;border-radius:5px;font-size:12px;white-space:nowrap}.research-status.is-unconfirmed{background:#faf5e9;border-color:#d8c39c;color:#815213;white-space:normal}.participation-nodes{padding:9px 0}.history-measurements{border-top:1px solid var(--line);margin-top:10px}.history-measurement{display:flex;align-items:center;gap:14px;padding:12px 0;border-bottom:1px solid var(--line)}.history-measurement>div{flex:1;min-width:0;overflow-wrap:anywhere}.history-measurement a{color:#086d79;font-size:13px}.history-measurement strong{font-size:19px;font-variant-numeric:tabular-nums;white-space:nowrap}.history-measurement small{font-size:12px;font-weight:400}.research-event summary{cursor:pointer;padding:10px 0;color:#086d79;font-size:13px;min-height:40px}.history-condition-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.research-event .el-button{margin-top:8px}.sample-research-timeline :deep(.el-timeline-item__timestamp){font-size:12px;color:var(--muted)}@media(max-width:640px){.research-event{padding:14px}.research-event header{flex-direction:column}.history-measurement{flex-wrap:wrap}.history-measurement>div{flex-basis:100%}.history-condition-grid{grid-template-columns:1fr}.sample-research-timeline{padding-left:0}.sample-research-timeline :deep(.el-timeline-item__wrapper){padding-left:23px}}</style>
